    existing = db.query_one("SELECT * FROM payments WHERE key=%s", idempotency_key)
    if existing:
        return existing
    # a concurrent retry can reach here before the first insert commits
    return db.insert("INSERT INTO payments (key, amount) VALUES (%s, %s)", idempotency_key, amount)
